{
  "uid": "devsecops-control",
  "title": "DevSecOps — admission and scan evidence",
  "schemaVersion": 39,
  "version": 2,
  "refresh": "30s",
  "time": {
    "from": "now-1h",
    "to": "now"
  },
  "tags": [
    "devsecops",
    "kyverno",
    "falco"
  ],
  "panels": [
    {
      "id": 1,
      "title": "Kyverno scrape UP",
      "type": "stat",
      "datasource": {
        "type": "prometheus",
        "uid": "prometheus"
      },
      "gridPos": {
        "x": 0,
        "y": 0,
        "w": 12,
        "h": 8
      },
      "targets": [
        {
          "refId": "A",
          "expr": "up{namespace=\"devsecops-system\",service=\"kyverno-svc-metrics\"}",
          "legendFormat": "{{policy_result}} {{pod}}",
          "instant": true
        }
      ]
    },
    {
      "id": 2,
      "title": "Policy outcomes (last hour)",
      "type": "timeseries",
      "datasource": {
        "type": "prometheus",
        "uid": "prometheus"
      },
      "gridPos": {
        "x": 12,
        "y": 0,
        "w": 12,
        "h": 8
      },
      "targets": [
        {
          "refId": "A",
          "expr": "sum by (policy_name,rule_result) (increase(kyverno_rule_results_total{policy_name=\"devsecops-workload-contract\"}[1h]))",
          "legendFormat": "{{rule_result}}"
        }
      ]
    },
    {
      "id": 3,
      "title": "Controller working set MiB",
      "type": "timeseries",
      "datasource": {
        "type": "prometheus",
        "uid": "prometheus"
      },
      "gridPos": {
        "x": 0,
        "y": 8,
        "w": 12,
        "h": 8
      },
      "targets": [
        {
          "refId": "A",
          "expr": "container_memory_working_set_bytes{namespace=\"devsecops-system\",container=\"kyverno\"}/1048576",
          "legendFormat": "{{policy_result}} {{pod}}"
        }
      ]
    },
    {
      "id": 4,
      "title": "Scanner CPU (transient Pods)",
      "type": "timeseries",
      "datasource": {
        "type": "prometheus",
        "uid": "prometheus"
      },
      "gridPos": {
        "x": 12,
        "y": 8,
        "w": 12,
        "h": 8
      },
      "targets": [
        {
          "refId": "A",
          "expr": "sum(rate(container_cpu_usage_seconds_total{namespace=\"devsecops-execution\",container=\"scanner\"}[2m]))",
          "legendFormat": "{{policy_result}} {{pod}}"
        }
      ]
    },
    {
      "id": 5,
      "type": "text",
      "title": "Scope and release records",
      "gridPos": {
        "x": 0,
        "y": 16,
        "w": 24,
        "h": 5
      },
      "options": {
        "mode": "markdown",
        "content": "Enforcement is limited to devsecops-execution. PetClinic promotion candidates are audited by CI; production has no new blocking webhook.\n\nJenkins petclinic-ci → DevSecOps stages → artifacts .devsecops/*.json: source gate, reviewed false positives, CycloneDX SBOM, admission probes, GitOps sync and unsigned release evidence.\n\nEmpty scanner charts after cleanup are expected. No claim of platform-wide vulnerability zero or signed supply-chain attestation."
      }
    },
    {
      "id": 20,
      "type": "row",
      "title": "Phase 4 — Runtime Security (local devops node)",
      "gridPos": {
        "x": 0,
        "y": 21,
        "w": 24,
        "h": 1
      },
      "collapsed": false
    },
    {
      "id": 21,
      "title": "Falco Events (last hour)",
      "type": "stat",
      "datasource": {
        "type": "loki",
        "uid": "loki"
      },
      "gridPos": {
        "x": 0,
        "y": 22,
        "w": 12,
        "h": 8
      },
      "targets": [
        {
          "refId": "A",
          "expr": "sum(count_over_time({app=\"platform-falco\",runtime_ruleset=\"59752c1132f0\"} | json | __error__=\"\" | source=\"syscall\" | rule=~\"Platform Runtime .*\"[1h]))",
          "queryType": "instant",
          "legendFormat": "{{rule}} {{output_fields_k8s_ns_name}} {{output_fields_k8s_pod_name}} {{node}}"
        }
      ],
      "description": "Current reviewed ruleset 59752c1132f0; historical rulesets remain queryable in Loki. Controlled tests and expected activity are not automatically attacks."
    },
    {
      "id": 22,
      "title": "Critical / High Runtime Alerts (Error or higher)",
      "type": "stat",
      "datasource": {
        "type": "loki",
        "uid": "loki"
      },
      "gridPos": {
        "x": 12,
        "y": 22,
        "w": 12,
        "h": 8
      },
      "targets": [
        {
          "refId": "A",
          "expr": "sum(count_over_time({app=\"platform-falco\",runtime_ruleset=\"59752c1132f0\"} | json | __error__=\"\" | source=\"syscall\" | rule=~\"Platform Runtime .*\" | priority=~\"Emergency|Alert|Critical|Error\" [1h]))",
          "queryType": "instant",
          "legendFormat": "{{rule}} {{output_fields_k8s_ns_name}} {{output_fields_k8s_pod_name}} {{node}}"
        }
      ],
      "description": "Current reviewed ruleset 59752c1132f0; historical rulesets remain queryable in Loki. Controlled tests and expected activity are not automatically attacks."
    },
    {
      "id": 23,
      "title": "Runtime Alerts by Rule",
      "type": "bargauge",
      "datasource": {
        "type": "loki",
        "uid": "loki"
      },
      "gridPos": {
        "x": 0,
        "y": 30,
        "w": 12,
        "h": 8
      },
      "targets": [
        {
          "refId": "A",
          "expr": "sum by (rule) (count_over_time({app=\"platform-falco\",runtime_ruleset=\"59752c1132f0\"} | json | __error__=\"\" | source=\"syscall\" | rule=~\"Platform Runtime .*\"[1h]))",
          "queryType": "instant",
          "legendFormat": "{{rule}}"
        }
      ],
      "options": {
        "orientation": "horizontal",
        "displayMode": "basic",
        "showUnfilled": true,
        "valueMode": "color",
        "reduceOptions": {
          "calcs": [
            "lastNotNull"
          ],
          "fields": "",
          "values": true,
          "limit": 50
        },
        "namePlacement": "left"
      },
      "description": "Current reviewed ruleset 59752c1132f0; historical rulesets remain queryable in Loki. Controlled tests and expected activity are not automatically attacks."
    },
    {
      "id": 24,
      "title": "Runtime Alerts by Namespace",
