        "w": 12,
        "h": 8
      },
      "targets": [
        {
          "refId": "A",
          "expr": "sum by (output_fields_k8s_ns_name) (count_over_time({app=\"platform-falco\",runtime_ruleset=\"59752c1132f0\"} | json | __error__=\"\" | source=\"syscall\" | rule=~\"Platform Runtime .*\"[1h]))",
          "queryType": "instant",
          "legendFormat": "{{output_fields_k8s_ns_name}}"
        }
      ],
      "options": {
        "orientation": "horizontal",
        "displayMode": "basic",
        "showUnfilled": true,
        "valueMode": "color",
        "reduceOptions": {
          "calcs": [
            "lastNotNull"
          ],
