          "values": true,
          "limit": 50
        },
        "namePlacement": "left"
      },
      "description": "Current reviewed ruleset 59752c1132f0; historical rulesets remain queryable in Loki. Controlled tests and expected activity are not automatically attacks."
    },
    {
      "id": 25,
      "title": "Runtime Alerts by Pod",
      "type": "bargauge",
      "datasource": {
        "type": "loki",
        "uid": "loki"
      },
      "gridPos": {
        "x": 0,
        "y": 38,
        "w": 12,
        "h": 8
      },
      "targets": [
        {
          "refId": "A",
          "expr": "sum by (output_fields_k8s_pod_name) (count_over_time({app=\"platform-falco\",runtime_ruleset=\"59752c1132f0\"} | json | __error__=\"\" | source=\"syscall\" | rule=~\"Platform Runtime .*\"[1h]))",
          "queryType": "instant",
