      },
      "description": "Current reviewed ruleset 59752c1132f0; historical rulesets remain queryable in Loki. Controlled tests and expected activity are not automatically attacks."
    },
    {
      "id": 26,
      "title": "Runtime Alerts by Node",
      "type": "bargauge",
      "datasource": {
        "type": "loki",
        "uid": "loki"
      },
      "gridPos": {
        "x": 12,
        "y": 38,
        "w": 12,
        "h": 8
      },
      "targets": [
        {
          "refId": "A",
          "expr": "sum by (node) (count_over_time({app=\"platform-falco\",runtime_ruleset=\"59752c1132f0\"} | json | __error__=\"\" | source=\"syscall\" | rule=~\"Platform Runtime .*\"[1h]))",
          "queryType": "instant",
